'use client';
import { useState } from 'react';
import * as XLSX from 'xlsx';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';

export default function AduanasPage() {
    const [loading, setLoading] = useState(false);
    const [resultado, setResultado] = useState(null);

    const subirArchivo = async (e) => {
        const file = e.target.files[0];
        if (!file) return;

        setLoading(true);
        const formData = new FormData();
        formData.append('file', file);

        try {
            const res = await fetch('/api/extract-invoice', { method: 'POST', body: formData });
            const data = await res.json();
            setResultado(data);
        } catch (error) {
            alert('Error ejecutando el motor híbrido.');
        }
        setLoading(false);
    };

    const textoSeguro = (valor) => {
        if (!valor) return 'N/A';
        if (typeof valor === 'object') return valor.nombre || valor.empresa || JSON.stringify(valor);
        return String(valor);
    };

    const exportarExcel = () => {
        if (!resultado?.productos) return;

        const datosFormateados = resultado.productos.map(item => ({
            Código: item.codigo,
            Descripción: item.descripcion,
            Origen: item.origen,
            Cantidad: item.cantidad,
            'Total ($)': item.p_total
        }));

        const hoja = XLSX.utils.json_to_sheet(datosFormateados);
        const libro = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(libro, hoja, 'Mercancia');
        XLSX.writeFile(libro, 'extraccion_aduanas.xlsx');
    };

    const exportarPDF = () => {
        if (!resultado?.productos) return;

        const doc = new jsPDF();

        doc.setFontSize(16);
        doc.text('LogisParse: Extracción de Factura de Aduana', 14, 20);

        doc.setFontSize(10);
        doc.text(`Remitente: ${textoSeguro(resultado.remitente_destinatario?.remitente)}`, 14, 30);
        doc.text(`Destinatario: ${textoSeguro(resultado.remitente_destinatario?.destinatario)}`, 14, 36);
        doc.text(`Incoterm: ${textoSeguro(resultado.remitente_destinatario?.incoterm)}`, 14, 42);

        const columnas = ['Código', 'Descripción', 'Origen', 'Cant.', 'Total ($)'];
        const filas = resultado.productos.map(item => [
            item.codigo,
            item.descripcion,
            item.origen,
            item.cantidad,
            item.p_total
        ]);

        autoTable(doc, {
            startY: 48,
            head: [columnas],
            body: filas,
            theme: 'striped',
            headStyles: { fillColor: [2, 132, 199] }
        });

        doc.save('extraccion_aduanas.pdf');
    };

    return (
        <main 
            style={{ 
                background: '#f1f5f9', // Fondo gris claro neutro para descartar el efecto marco
                minHeight: '100vh', 
                width: '100%', 
                display: 'grid', 
                placeItems: 'center', 
                padding: '1.5rem 1rem',
                boxSizing: 'border-box'
            }}
        >
            {/* Contenedor más compacto (max-w-xl) */}
            <div className="max-w-xl w-full space-y-4">
                
                {/* TARJETA DE INTRODUCCIÓN COMPACTA */}
                <div className="bg-white rounded-xl shadow-md border border-slate-200/80 p-5 text-center text-slate-800">
                    <div className="inline-flex items-center justify-center w-10 h-10 rounded-lg bg-sky-100 text-sky-600 mb-2 border border-sky-200 shadow-sm">
                        ⚡
                    </div>
                    <h2 className="text-xl md:text-2xl font-extrabold tracking-tight text-slate-900">
                        LogisParse: Extracción Híbrida
                    </h2>
                    <p className="text-xs md:text-sm text-slate-500 mt-1 max-w-sm mx-auto">
                        Procesamiento local seguro y estructurado de documentos de aduana.
                    </p>
                </div>

                {/* TARJETA DE CARGA Y RESULTADOS COMPACTA */}
                <div className="bg-white rounded-xl shadow-md border border-slate-200/80 p-5 md:p-6 text-slate-800">
                    
                    {/* Zona de carga */}
                    <div className="relative border-2 border-dashed border-sky-300 hover:border-sky-500 transition-colors duration-200 rounded-lg p-6 bg-sky-50/30 text-center cursor-pointer group">
                        <input 
                            type="file" 
                            accept=".pdf, image/jpeg, image/png" 
                            onChange={subirArchivo} 
                            disabled={loading} 
                            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer disabled:cursor-not-allowed" 
                        />
                        <div className="flex flex-col items-center justify-center space-y-1.5">
                            <div className="p-2 bg-white rounded-full border border-sky-200 shadow-sm group-hover:scale-105 transition-transform">
                                📄
                            </div>
                            <p className="text-xs md:text-sm font-medium text-slate-700">
                                Arrastra tu factura o <span className="text-sky-600 font-semibold underline">haz clic para buscar</span>
                            </p>
                            <p className="text-[11px] text-slate-400">Soporta PDF, PNG y JPG</p>
                        </div>
                    </div>

                    {/* Feedback de Carga */}
                    {loading && (
                        <div className="mt-4 p-3 rounded-lg bg-sky-50 border border-sky-200 flex items-center justify-center space-x-2 shadow-sm">
                            <span className="animate-spin text-base">⚙️</span>
                            <p className="text-xs text-sky-800 font-medium">
                                Ejecutando Python + QVAC localmente...
                            </p>
                        </div>
                    )}

                    {/* Resultados */}
                    {resultado && (
                        <div className="mt-6 text-left space-y-5">
                            
                            <div className="border-b border-slate-100 pb-1.5">
                                <span className="text-[11px] font-bold uppercase tracking-wider text-sky-600">
                                    Metadatos Extraídos
                                </span>
                            </div>

                            {/* Tarjetas de Metadatos */}
                            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                                <div className="bg-slate-50 border border-slate-200/60 p-3 rounded-lg">
                                    <span className="text-[10px] text-slate-400 font-bold uppercase block">Remitente</span>
                                    <p className="font-semibold text-slate-800 mt-0.5 text-xs truncate" title={textoSeguro(resultado.remitente_destinatario?.remitente)}>
                                        {textoSeguro(resultado.remitente_destinatario?.remitente)}
                                    </p>
                                </div>
                                <div className="bg-slate-50 border border-slate-200/60 p-3 rounded-lg">
                                    <span className="text-[10px] text-slate-400 font-bold uppercase block">Destinatario</span>
                                    <p className="font-semibold text-slate-800 mt-0.5 text-xs truncate" title={textoSeguro(resultado.remitente_destinatario?.destinatario)}>
                                        {textoSeguro(resultado.remitente_destinatario?.destinatario)}
                                    </p>
                                </div>
                                <div className="bg-slate-50 border border-slate-200/60 p-3 rounded-lg">
                                    <span className="text-[10px] text-slate-400 font-bold uppercase block">Incoterm</span>
                                    <p className="font-semibold text-slate-800 mt-0.5 text-xs truncate" title={textoSeguro(resultado.remitente_destinatario?.incoterm)}>
                                        {textoSeguro(resultado.remitente_destinatario?.incoterm)}
                                    </p>
                                </div>
                            </div>

                            {/* Tabla de Mercancía */}
                            <div className="overflow-x-auto rounded-lg border border-slate-200 bg-white">
                                <table className="min-w-full text-xs text-left text-slate-600">
                                    <thead className="bg-slate-50 text-slate-700 font-semibold uppercase text-[10px] border-b border-slate-200">
                                        <tr>
                                            <th className="px-3 py-2">Código</th>
                                            <th className="px-3 py-2">Descripción</th>
                                            <th className="px-3 py-2">Origen</th>
                                            <th className="px-3 py-2 text-right">Cant.</th>
                                            <th className="px-3 py-2 text-right">Total ($)</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100">
                                        {resultado.productos?.map((item, index) => (
                                            <tr key={index} className="hover:bg-slate-50 transition-colors">
                                                <td className="px-3 py-2 font-mono text-[11px] text-sky-700 font-semibold">{item.codigo}</td>
                                                <td className="px-3 py-2 truncate max-w-[150px] text-slate-800" title={item.descripcion}>{item.descripcion}</td>
                                                <td className="px-3 py-2 text-slate-500">{item.origen}</td>
                                                <td className="px-3 py-2 text-right text-slate-700">{item.cantidad}</td>
                                                <td className="px-3 py-2 text-right font-bold text-emerald-600">{item.p_total}</td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>

                            {/* BOTONES DE DESCARGA */}
                            <div className="pt-3 border-t border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-3">
                                <p className="text-[11px] text-slate-400">
                                    🔒 Extracción local segura.
                                </p>

                                <div className="flex items-center space-x-2 w-full sm:w-auto">
                                    <button
                                        onClick={exportarExcel}
                                        className="flex-1 sm:flex-none px-3 py-1.5 text-xs font-semibold text-emerald-800 bg-emerald-100 hover:bg-emerald-200 border border-emerald-300 rounded-lg transition-all flex items-center justify-center space-x-1.5"
                                    >
                                        <span>📊</span>
                                        <span>Excel</span>
                                    </button>
                                    <button
                                        onClick={exportarPDF}
                                        className="flex-1 sm:flex-none px-3 py-1.5 text-xs font-semibold text-rose-800 bg-rose-100 hover:bg-rose-200 border border-rose-300 rounded-lg transition-all flex items-center justify-center space-x-1.5"
                                    >
                                        <span>📕</span>
                                        <span>PDF</span>
                                    </button>
                                </div>
                            </div>

                        </div>
                    )}
                </div>
            </div>
        </main>
    );
}